<div id="chacStudio" class="chac-studio"><style>
.chac-studio{max-width:980px;margin:auto;padding:14px;color:var(--body-color,#222)}.chac-studio *{box-sizing:border-box}.chac-layout{display:grid;grid-template-columns:minmax(230px,.9fr) minmax(280px,1.1fr);gap:16px}.chac-preview{background:#e0e7ff;border-radius:18px;overflow:hidden;display:flex;justify-content:center}.chac-preview canvas{width:100%;max-width:360px;height:auto}.chac-options{display:grid;grid-template-columns:1fr 1fr;gap:9px}.chac-option{padding:10px;border-radius:12px;background:rgba(127,127,127,.09)}.chac-option label{display:block;font-size:12px;font-weight:700;margin-bottom:5px}.chac-option select{width:100%;min-height:36px}.chac-buttons{display:flex;gap:8px;margin-top:12px}.chac-btn{border:0;border-radius:9px;padding:10px 14px;background:#6366f1;color:#fff;font-weight:700;cursor:pointer}.chac-btn.secondary{background:#64748b}.chac-status{margin-top:10px;min-height:20px;font-size:13px}@media(max-width:650px){.chac-layout{grid-template-columns:1fr}}
</style><h2>Maak je eigen avatar</h2><p>Kies je eigen cartoonstijl en sla hem op als profielfoto.</p><div class="chac-layout"><div><div class="chac-preview"><canvas id="chacCanvas" width="360" height="360" aria-label="Avatarvoorbeeld"></canvas></div><div class="chac-buttons"><button class="chac-btn secondary" id="chacRandom" type="button">Verras me</button><button class="chac-btn" id="chacSave" type="button">Avatar opslaan</button></div><div class="chac-status" id="chacStatus" role="status" aria-live="polite"></div></div><div class="chac-options">
<div class="chac-option"><label for="chacSkin">Huidskleur</label><select id="chacSkin"><option value="#f7d7bd">Licht</option><option value="#e8b58e" selected>Warm licht</option><option value="#c98256">Medium</option><option value="#8f563b">Donker</option><option value="#593624">Diep donker</option></select></div>
<div class="chac-option"><label for="chacHair">Haarkleur</label><select id="chacHair"><option value="#241b18">Zwartbruin</option><option value="#5b3524" selected>Bruin</option><option value="#c58a42">Blond</option><option value="#a74335">Rood</option><option value="#6c55c7">Paars</option><option value="#e45d9c">Roze</option></select></div>
<div class="chac-option"><label for="chacEyes">Oogkleur</label><select id="chacEyes"><option value="#426a9a">Blauw</option><option value="#5d8a51">Groen</option><option value="#69462f" selected>Bruin</option><option value="#242424">Donker</option></select></div>
<div class="chac-option"><label for="chacShirt">Kleding</label><select id="chacShirt"><option value="#6366f1" selected>Indigo</option><option value="#ec4899">Roze</option><option value="#06b6d4">Cyaan</option><option value="#16a34a">Groen</option><option value="#1f2937">Zwart</option><option value="#f59e0b">Goud</option></select></div>
<div class="chac-option"><label for="chacHairStyle">Kapsel</label><select id="chacHairStyle"><option value="short">Kort</option><option value="long">Lang</option><option value="curly">Krullen</option><option value="spiky">Piekjes</option><option value="bald">Kaal</option></select></div>
<div class="chac-option"><label for="chacFace">Expressie</label><select id="chacFace"><option value="smile">Glimlach</option><option value="neutral">Neutraal</option><option value="happy">Blij</option><option value="cool">Stoer</option></select></div>
<div class="chac-option"><label for="chacBg">Achtergrond</label><select id="chacBg"><option value="#e0e7ff">Lavendel</option><option value="#fce7f3">Roze</option><option value="#cffafe">Lichtblauw</option><option value="#dcfce7">Mint</option><option value="#ffedd5">Perzik</option><option value="#1f2937">Donker</option></select></div>
<div class="chac-option"><label for="chacAccessory">Accessoire</label><select id="chacAccessory"><option value="none">Geen</option><option value="glasses">Bril</option><option value="sunglasses">Zonnebril</option><option value="cap">Pet</option><option value="earrings">Oorbellen</option></select></div></div></div></div>
<script>(function(){'use strict';var r=document.getElementById('chacStudio');if(!r||r.dataset.init)return;r.dataset.init='1';var c=r.querySelector('#chacCanvas'),x=c.getContext('2d');function v(n){return r.querySelector('#chac'+n).value}function draw(){x.clearRect(0,0,360,360);x.fillStyle=v('Bg');x.fillRect(0,0,360,360);x.globalAlpha=.16;x.fillStyle='#fff';x.beginPath();x.arc(180,150,130,0,Math.PI*2);x.fill();x.globalAlpha=1;x.fillStyle=v('Shirt');x.beginPath();x.moveTo(56,360);x.lineTo(75,278);x.quadraticCurveTo(180,222,285,278);x.lineTo(304,360);x.fill();x.fillStyle=v('Skin');x.fillRect(151,220,58,60);x.beginPath();x.ellipse(105,164,17,27,0,0,Math.PI*2);x.ellipse(255,164,17,27,0,0,Math.PI*2);x.ellipse(180,158,77,96,0,0,Math.PI*2);x.fill();var h=v('HairStyle');x.fillStyle=v('Hair');if(h!=='bald'){if(h==='long'){x.beginPath();x.ellipse(180,112,80,56,0,Math.PI,Math.PI*2);x.fill();x.fillRect(101,110,24,158);x.fillRect(235,110,24,158)}else if(h==='curly'){for(var i=0;i<8;i++){x.beginPath();x.arc(110+i*20,88+(i%2)*-7,23,0,Math.PI*2);x.fill()}}else if(h==='spiky'){x.beginPath();x.moveTo(103,150);x.lineTo(122,90);x.lineTo(145,111);x.lineTo(180,58);x.lineTo(207,106);x.lineTo(236,79);x.lineTo(257,150);x.closePath();x.fill()}else{x.beginPath();x.ellipse(180,103,78,46,0,Math.PI,Math.PI*2);x.fill()}}x.strokeStyle=v('Hair');x.lineWidth=5;x.beginPath();x.moveTo(130,135);x.lineTo(157,132);x.moveTo(203,132);x.lineTo(230,135);x.stroke();x.fillStyle='#fff';x.beginPath();x.ellipse(145,152,13,9,0,0,Math.PI*2);x.ellipse(215,152,13,9,0,0,Math.PI*2);x.fill();x.fillStyle=v('Eyes');x.beginPath();x.arc(146,152,6,0,Math.PI*2);x.arc(214,152,6,0,Math.PI*2);x.fill();x.strokeStyle='#783b36';x.lineWidth=4;x.beginPath();if(v('Face')==='neutral'){x.moveTo(158,207);x.lineTo(202,207)}else if(v('Face')==='cool'){x.moveTo(158,204);x.quadraticCurveTo(180,213,202,204)}else{x.moveTo(156,201);x.quadraticCurveTo(180,v('Face')==='happy'?232:221,204,201)}x.stroke();var a=v('Accessory');if(a==='glasses'||a==='sunglasses'){x.strokeStyle='#222';x.fillStyle=a==='sunglasses'?'#222':'rgba(255,255,255,.3)';x.lineWidth=4;x.beginPath();x.rect(124,139,42,27);x.rect(194,139,42,27);x.moveTo(166,150);x.lineTo(194,150);x.fill();x.stroke()}else if(a==='cap'){x.fillStyle=v('Hair');x.beginPath();x.ellipse(180,91,80,22,0,Math.PI,Math.PI*2);x.fill();x.fillRect(105,91,155,8)}else if(a==='earrings'){x.fillStyle='#fbbf24';x.beginPath();x.arc(103,190,5,0,Math.PI*2);x.arc(257,190,5,0,Math.PI*2);x.fill()}}r.querySelectorAll('select').forEach(function(e){e.addEventListener('change',draw)});r.querySelector('#chacRandom').addEventListener('click',function(){r.querySelectorAll('select').forEach(function(e){e.selectedIndex=Math.floor(Math.random()*e.options.length)});draw()});r.querySelector('#chacSave').addEventListener('click',function(){var b=this,s=r.querySelector('#chacStatus');b.disabled=true;s.textContent='Opslaan…';fetch('addons/chathype_avatar_creator/system/save_avatar.php',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({image:c.toDataURL('image/png')})}).then(function(q){return q.json().then(function(j){if(!q.ok||!j.success)throw new Error(j.error||'Opslaan mislukt');return j})}).then(function(){s.textContent='Avatar opgeslagen als profielfoto.'}).catch(function(e){s.textContent='Fout: '+e.message}).finally(function(){b.disabled=false})});draw()})();</script>
